import{_ as p,a0 as l,w as o,s as u,I as i,x as n,a1 as e,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中驗證 ISO 鏡像 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中驗證 ISO 鏡像 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中驗證 ISO 鏡像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中驗證 ISO 鏡像 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Verify ISO Images In Linux","title":"如何在 Linux 中驗證 ISO 鏡像","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Verify ISO Images In Linux.md","filePath":"[post].md"}'),g={name:"201908/20190805 How To Verify ISO Images In Linux.md"};function d(h,s,k,b,c,m){const a=l("Link");return o(),u("div",null,[s[21]||(s[21]=i("h1",{id:"如何在-linux-中驗證-iso-鏡像",tabindex:"-1"},[n("如何在 Linux 中驗證 ISO 鏡像 "),i("a",{class:"header-anchor",href:"#如何在-linux-中驗證-iso-鏡像","aria-label":"Permalink to “如何在 Linux 中驗證 ISO 鏡像”"},"​")],-1)),s[22]||(s[22]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/07/Verify-ISO-Images-In-Linux-720x340.png",alt:"如何在 Linux 中校驗 ISO 鏡像"})],-1)),i("p",null,[s[2]||(s[2]=n("你從喜愛的 Linux 發行版的官方網站或第三方網站下載了它的 ISO 鏡像之後，接下來要做什麼呢？是",-1)),e(a,{href:"https://www.ostechnix.com/etcher-beauitiful-app-create-bootable-sd-cards-usb-drives/"},{default:t(()=>[...s[0]||(s[0]=[n("創建可啓動介質",-1)])]),_:1}),s[3]||(s[3]=n("並開始安裝系統嗎？並不是，請稍等一下。在開始使用它之前，強烈建議你檢查一下你剛下載到本地系統中的 ISO 文件是否是下載鏡像站點中 ISO 文件的一個精確拷貝。因為在前幾年 ",-1)),e(a,{href:"https://blog.linuxmint.com/?p=2994"},{default:t(()=>[...s[1]||(s[1]=[n("Linux Mint 的網站被攻破了",-1)])]),_:1}),s[4]||(s[4]=n("，並且攻擊者創建了一個包含後門的經過修改的 Linux Mint ISO 文件。 所以驗證下載的 Linux ISO 鏡像的可靠性和完整性是非常重要的一件事兒。假如你不知道如何在 Linux 中驗證 ISO 鏡像，本次的簡要介紹將給予你幫助，請接着往下看！",-1))]),s[23]||(s[23]=r(`<h3 id="在-linux-中驗證-iso-鏡像" tabindex="-1">在 Linux 中驗證 ISO 鏡像 <a class="header-anchor" href="#在-linux-中驗證-iso-鏡像" aria-label="Permalink to “在 Linux 中驗證 ISO 鏡像”">​</a></h3><p>我們可以使用 ISO 鏡像的“校驗和”來驗證 ISO 鏡像。校驗和是一系列字母和數字的組合，用來檢驗下載文件的數據是否有錯以及驗證其可靠性和完整性。當前存在不同類型的校驗和，例如 SHA-0、SHA-1、SHA-2（224、256、384、512）和 MD5。MD5 校驗和最為常用，但對於現代的 Linux 發行版，SHA-256 最常被使用。</p><p>我們將使用名為 <code>gpg</code> 和 <code>sha256</code> 的兩個工具來驗證 ISO 鏡像的可靠性和完整性。</p><h4 id="下載校驗和及簽名" tabindex="-1">下載校驗和及簽名 <a class="header-anchor" href="#下載校驗和及簽名" aria-label="Permalink to “下載校驗和及簽名”">​</a></h4><p>針對本篇指南的目的，我將使用 Ubuntu 18.04 LTS 服務器 ISO 鏡像來做驗證，但對於其他的 Linux 發行版應該也是適用的。</p><p>在靠近 Ubuntu 下載頁的最上端，你將看到一些額外的文件（校驗和及簽名），正如下面展示的圖片那樣：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-18.04-checksum-and-signature.png" alt="Ubuntu 18.04 的校驗和及簽名"></p><p>其中名為 <code>SHA256SUMS</code> 的文件包含了這裏所有可獲取鏡像的校驗和，而 <code>SHA256SUMS.gpg</code> 文件則是這個文件的 GnuPG 簽名。在下面的步驟中，我們將使用這個簽名文件來 <strong>驗證</strong> 校驗和文件。</p><p>下載 Ubuntu 的 ISO 鏡像文件以及剛才提到的那兩個文件，然後將它們放到同一目錄下，例如這裏的 <code>ISO</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ISO/</span></span>
<span class="line"><span>SHA256SUMS SHA256SUMS.gpg ubuntu-18.04.2-live-server-amd64.iso</span></span></code></pre></div><p>如你所見，我已經下載了 Ubuntu 18.04.2 LTS 服務器版本的鏡像，以及對應的校驗和文件和簽名文件。</p><h4 id="下載有效的簽名秘鑰" tabindex="-1">下載有效的簽名秘鑰 <a class="header-anchor" href="#下載有效的簽名秘鑰" aria-label="Permalink to “下載有效的簽名秘鑰”">​</a></h4><p>現在，使用下面的命令來下載正確的簽名秘鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --keyid-format long --keyserver hkp://keyserver.ubuntu.com --recv-keys 0x46181433FBB75451 0xD94AA3F0EFE21092</span></span></code></pre></div><p>示例輸出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg: key D94AA3F0EFE21092: 57 signatures not checked due to missing keys</span></span>
<span class="line"><span>gpg: key D94AA3F0EFE21092: public key &quot;Ubuntu CD Image Automatic Signing Key (2012) &lt;[email protected]&gt;&quot; imported</span></span>
<span class="line"><span>gpg: key 46181433FBB75451: 105 signatures not checked due to missing keys</span></span>
<span class="line"><span>gpg: key 46181433FBB75451: public key &quot;Ubuntu CD Image Automatic Signing Key &lt;[email protected]&gt;&quot; imported</span></span>
<span class="line"><span>gpg: no ultimately trusted keys found</span></span>
<span class="line"><span>gpg: Total number processed: 2</span></span>
<span class="line"><span>gpg: imported: 2</span></span></code></pre></div><h4 id="驗證-sha-256-校驗和" tabindex="-1">驗證 SHA-256 校驗和 <a class="header-anchor" href="#驗證-sha-256-校驗和" aria-label="Permalink to “驗證 SHA-256 校驗和”">​</a></h4><p>接下來我們將使用簽名來驗證校驗和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --keyid-format long --verify SHA256SUMS.gpg SHA256SUMS</span></span></code></pre></div><p>下面是示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg: Signature made Friday 15 February 2019 04:23:33 AM IST</span></span>
<span class="line"><span>gpg: using DSA key 46181433FBB75451</span></span>
<span class="line"><span>gpg: Good signature from &quot;Ubuntu CD Image Automatic Signing Key &lt;[email protected]&gt;&quot; [unknown]</span></span>
<span class="line"><span>gpg: WARNING: This key is not certified with a trusted signature!</span></span>
<span class="line"><span>gpg: There is no indication that the signature belongs to the owner.</span></span>
<span class="line"><span>Primary key fingerprint: C598 6B4F 1257 FFA8 6632 CBA7 4618 1433 FBB7 5451</span></span>
<span class="line"><span>gpg: Signature made Friday 15 February 2019 04:23:33 AM IST</span></span>
<span class="line"><span>gpg: using RSA key D94AA3F0EFE21092</span></span>
<span class="line"><span>gpg: Good signature from &quot;Ubuntu CD Image Automatic Signing Key (2012) &lt;[email protected]&gt;&quot; [unknown]</span></span>
<span class="line"><span>gpg: WARNING: This key is not certified with a trusted signature!</span></span>
<span class="line"><span>gpg: There is no indication that the signature belongs to the owner.</span></span>
<span class="line"><span>Primary key fingerprint: 8439 38DF 228D 22F7 B374 2BC0 D94A A3F0 EFE2 1092</span></span></code></pre></div><p>假如你在輸出中看到 <code>Good signature</code> 字樣，那麼該校驗和文件便是由 Ubuntu 開發者製作的，並且由秘鑰文件的所屬者簽名認證。</p><h4 id="檢驗下載的-iso-文件" tabindex="-1">檢驗下載的 ISO 文件 <a class="header-anchor" href="#檢驗下載的-iso-文件" aria-label="Permalink to “檢驗下載的 ISO 文件”">​</a></h4><p>下面讓我們繼續檢查下載的 ISO 文件是否和所給的校驗和相匹配。為了達到該目的，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sha256sum -c SHA256SUMS 2&gt;&amp;1 | grep OK</span></span>
<span class="line"><span>ubuntu-18.04.2-live-server-amd64.iso: OK</span></span></code></pre></div><p>假如校驗和是匹配的，你將看到 <code>OK</code> 字樣，這意味着下載的文件是合法的，沒有被改變或篡改過。</p><p>假如你沒有獲得類似的輸出，或者看到不同的輸出，則該 ISO 文件可能已經被修改過或者沒有被正確地下載。你必須從一個更好的下載源重新下載該文件。</p><p>某些 Linux 發行版已經在它的下載頁面中包含了校驗和。例如 Pop!_os 的開發者在他們的下載頁面中提供了所有 ISO 鏡像的 SHA-256 校驗和，這樣你就可以快速地驗證這些 ISO 鏡像。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Pop-os-SHA256-sum.png" alt="Pop os 位於其下載頁面中的 SHA256 校驗和"></p><p>在下載完 ISO 鏡像文件後，可以使用下面的命令來驗證它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sha256sum Soft_backup/ISOs/pop-os_18.04_amd64_intel_54.iso</span></span></code></pre></div><p>示例輸出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>680e1aa5a76c86843750e8120e2e50c2787973343430956b5cbe275d3ec228a6 Soft_backup/ISOs/pop-os_18.04_amd64_intel_54.iso</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Pop-os-SHA256-sum-value.png" alt="Pop os 的 SHA256 校驗和的值"></p><p>在上面的輸出中，以 <code>680elaa</code> 開頭的部分為 SHA-256 校驗和的值。請將該值與位於下載頁面中提供的 SHA-256 校驗和的值進行比較，如果這兩個值相同，那説明這個下載的 ISO 文件是合法的，與它的原有狀態相比沒有經過更改或者篡改。萬事俱備，你可以進行下一步了！</p><p>上面的內容便是我們如何在 Linux 中驗證一個 ISO 文件的可靠性和完整性的方法。無論你是從官方站點或者第三方站點下載 ISO 文件，我們總是推薦你在使用它們之前做一次簡單的快速驗證。希望本篇的內容對你有所幫助。</p><p>參考文獻：</p>`,37)),i("ul",null,[i("li",null,[e(a,{href:"https://tutorials.ubuntu.com/tutorial/tutorial-how-to-verify-ubuntu"},{default:t(()=>[...s[5]||(s[5]=[n("https://tutorials.ubuntu.com/tutorial/tutorial-how-to-verify-ubuntu",-1)])]),_:1})])]),s[24]||(s[24]=i("hr",null,null,-1)),i("p",null,[s[7]||(s[7]=n("via: ",-1)),e(a,{href:"https://www.ostechnix.com/how-to-verify-iso-images-in-linux/"},{default:t(()=>[...s[6]||(s[6]=[n("https://www.ostechnix.com/how-to-verify-iso-images-in-linux/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[8]||(s[8]=[n("sk",-1)])]),_:1}),s[13]||(s[13]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 譯者：",-1)),e(a,{href:"https://github.com/FSSlc"},{default:t(()=>[...s[10]||(s[10]=[n("FSSlc",-1)])]),_:1}),s[15]||(s[15]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[n("Linux中國",-1)])]),_:1}),s[20]||(s[20]=n(" 榮譽推出",-1))])])}const y=p(g,[["render",d]]);export{x as __pageData,y as default};
